// ─── KaTeX Renderer ───────────────────────────────────────────────────────────
function KaTeX({ expression, display = false }) {
  const ref = useRef(null);
  useEffect(() => {
    if (ref.current) {
      try {
        katex.render(expression, ref.current, {
          displayMode: display,
          throwOnError: false,
          strict: false,
        });
      } catch (e) {
        ref.current.textContent = expression;
      }
    }
  }, [expression, display]);
  return (
    <span
      ref={ref}
      style={{ display: display ? "block" : "inline" }}
    />
  );
}

